def solve(s):
    stack=[]
    pairs={")":"(","]":"[","}":"{"}
    for c in s:
        if c in "([{": stack.append(c)
        elif c in pairs:
            if not stack or stack.pop()!=pairs[c]: return False
    return not stack

def solve(xs):
    if not xs: return ""
    p=xs[0]
    for s in xs[1:]:
        while not s.startswith(p): p=p[:-1]
    return p
